from typing import Tuple

_HEX_DIGITS = set("0123456789abcdefABCDEF")


def _decode_hex(hex_str: str) -> bytes:
    if not isinstance(hex_str, str):
        raise ValueError("hex_str must be a string")

    s = hex_str.strip()
    if not s:
        return b""

    # Handle literal \xHH byte tokens, e.g. r"\xF3\xBE"
    if "\\x" in s:
        parts = []
        for token in s.split():
            if len(token) != 4 or not token.startswith("\\x"):
                raise ValueError(f"invalid hex string: {hex_str!r}")
            pair = token[2:]
            if any(ch not in _HEX_DIGITS for ch in pair):
                raise ValueError(f"invalid hex string: {hex_str!r}")
            parts.append(pair)
        return bytes.fromhex("".join(parts))

    try:
        return bytes.fromhex(s)
    except ValueError as exc:
        raise ValueError(f"invalid hex string: {hex_str!r}") from exc


def salted_sha256_from_hex(hex_str: str, salt: bytes) -> Tuple[str, str]:
    data = _decode_hex(hex_str)
    digest = hashlib.sha256(salt + data).hexdigest()
    salt_b64 = base64.b64encode(salt).decode("ascii")
    return salt_b64, digest
