import json
from collections import Counter

def count_urls_in_json(json_str: str, top_n: int = 10) -> dict:
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    counts = Counter()
    stack = [data]

    while stack:
        node = stack.pop()

        if isinstance(node, dict):
            stack.extend(reversed(list(node.values())))
        elif isinstance(node, list):
            stack.extend(reversed(node))
        elif isinstance(node, str) and node.startswith(("http://", "https://", "www.")):
            counts[node] += 1

    if top_n is None:
        selected = set(counts)
    elif top_n <= 0:
        selected = set()
    else:
        selected = {url for url, _ in counts.most_common(top_n)}

    return {url: counts[url] for url in counts if url in selected}
```

