def error_times_and_average(logs):
    error_times = []

    for line in logs:
        parts = line.split()
        if len(parts) < 3:
            continue

        level = parts[2].upper().rstrip(':')
        if level == 'ERROR':
            hour, minute = map(int, parts[1].split(':')[:2])
            error_times.append((hour, minute))

    if not error_times:
        return [], (0, 0)

    total_minutes = sum(h * 60 + m for h, m in error_times)
    avg_minutes = total_minutes // len(error_times)

    return error_times, (avg_minutes // 60, avg_minutes % 60)
