def underscore_target_phrases(target_phrases, sentences):
    # Lowercase target phrases once; skip empty phrases.
    phrases = [p.lower() for p in target_phrases if p]

    result = []

    for sentence in sentences:
        lowered = sentence.lower()
        chars = list(lowered)

        # Find every occurrence, including overlapping ones, in the
        # original lowercased sentence and mark its spaces for replacement.
        for phrase in phrases:
            start = 0
            while True:
                idx = lowered.find(phrase, start)
                if idx == -1:
                    break

                for offset, ch in enumerate(phrase):
                    if ch == ' ':
                        chars[idx + offset] = '_'

                start = idx + 1  # allow overlapping matches

        result.append(''.join(chars))

    return result
