import ast

def _find_matching_brace(text, start):
    """Return the index of the '}' matching the '{' at start, or -1."""
    n = len(text)
    i = start
    depth = 0

    while i < n:
        c = text[i]

        if c == '{':
            depth += 1
            i += 1
        elif c == '}':
            depth -= 1
            i += 1
            if depth == 0:
                return i - 1
        elif c == '#':  # comment: skip to end of line
            while i < n and text[i] != '\n':
                i += 1
        elif c in ('"', "'"):  # string literal: skip it entirely
            quote = c
            if text[i:i+3] == quote * 3:  # triple-quoted string
                i += 3
                while i < n:
                    if text[i] == '\\':
                        i += 2
                    elif text[i:i+3] == quote * 3:
                        i += 3
                        break
                    else:
                        i += 1
            else:  # single-quoted string
                i += 1
                while i < n:
                    if text[i] == '\\':
                        i += 2
                    elif text[i] == quote:
                        i += 1
                        break
                    else:
                        i += 1
        else:
            i += 1

    return -1


def extract_dicts(text):
    """Extract all outermost Python dict literals from text."""
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == '{':
            end = _find_matching_brace(text, i)
            if end != -1:
                candidate = text[i:end + 1]
                try:
                    value = ast.literal_eval(candidate)
                except Exception:
                    value = None

                if isinstance(value, dict):
                    result.append(value)
                    i = end + 1
                    continue
                if value is not None:  # valid non-dict literal, e.g. a set
                    i = end + 1
                    continue
        i += 1

    return result
