                    elif text[i] == quote:
                        i += 1
                        break
                    else:
                        i += 1
        else:
            i += 1

    return -1


def extract_dicts(text):
    """Extract all outermost Python dict literals from text."""
    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i] == '{':
            end = _find_matching_brace(text, i)
            if end != -1:
                candidate = text[i:end + 1]
                try:
                    value = ast.literal_eval(candidate)
                except Exception:
                    value = None

                if isinstance(value, dict):
                    result.append(value)
                    i = end + 1
                    continue
                if value is not None:  # valid non-dict literal, e.g. a set
                    i = end + 1
                    continue
        i += 1

    return result

