import ast

def parse_dict_lines(texts):
    """
    Parse each line of each text as a Python dictionary literal.

    Returns a flat list of dicts in file order, then line order.
    Raises ValueError if any line is not a valid dictionary literal.
    """
    result = []

    for file_no, text in enumerate(texts, start=1):
        for line_no, line in enumerate(text.splitlines(), start=1):
            try:
                value = ast.literal_eval(line)
            except Exception as exc:
                raise ValueError(
                    f"file {file_no}, line {line_no}: invalid dictionary literal: {line!r}"
                ) from exc

            if not isinstance(value, dict):
                raise ValueError(
                    f"file {file_no}, line {line_no}: not a dictionary literal: {line!r}"
                )

            result.append(value)

    return result

