import re

def top_words_without_urls(text, top_n):
    if top_n <= 0:
        return []

    # Remove URLs: http:// or https:// followed by non-whitespace
    cleaned = re.sub(r'https?://\S*', ' ', text)

    # Extract words: runs of letters, digits, or underscores
    words = re.findall(r'\w+', cleaned)

    counts = {}
    first_seen = {}

    for i, word in enumerate(words):
        counts[word] = counts.get(word, 0) + 1
        first_seen.setdefault(word, i)

    # Most frequent first; ties broken by first occurrence
    result = sorted(counts.items(), key=lambda kv: (-kv[1], first_seen[kv[0]]))

    return result[:top_n]

