import base64
import binascii
import json
import unicodedata


def decode_base64_json_values(json_text: str) -> dict:
    """
    Decode a JSON object whose values are base64-encoded UTF-8 strings.

    Returns a dict with the same keys mapped to NFC-normalized decoded text.
    Raises ValueError for invalid JSON, non-object JSON, non-string values,
    invalid base64, or invalid UTF-8.
    """
    if not isinstance(json_text, str):
        raise ValueError("json_text must be a string")

    try:
        data = json.loads(json_text)
    except json.JSONDecodeError as exc:
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON text must contain an object")

    result = {}

    for key, value in data.items():
        if not isinstance(value, str):
            raise ValueError(f"Value for key {key!r} is not a base64-encoded string")

        try:
            decoded_bytes = base64.b64decode(value, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise ValueError(f"Invalid base64 for key {key!r}: {exc}") from exc

        try:
            decoded_text = decoded_bytes.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(f"Decoded value for key {key!r} is not valid UTF-8: {exc}") from exc

        result[key] = unicodedata.normalize("NFC", decoded_text)

    return result

import re

def count_stopwords(text, stopwords):
    # Drop URLs: http:// or https:// up to the next whitespace
    text = re.sub(r'https?://\S*', ' ', text)

    # Split into runs of letters, digits, or underscores
    words = re.findall(r'\w+', text)

    counts = {}
    order = []

    for word in words:
        if word in stopwords:
            if word not in counts:
                counts[word] = 0
                order.append(word)
            counts[word] += 1

    return [(word, counts[word]) for word in order]

