import re


def error_times_and_average(logs):
    times = []
    for line in logs:
        if 'ERROR' not in line:
            continue
        match = re.search(r'(\d{1,2}):(\d{2}):(\d{2})', line)
        if match:
            hour = int(match.group(1))
            minute = int(match.group(2))
            times.append((hour, minute))
    if not times:
        return ([], (0, 0))
    total_minutes = sum(h * 60 + m for h, m in times)
    average_minutes = total_minutes // len(times)
    return (times, (average_minutes // 60, average_minutes % 60))

