def count_subset_sums(elements, subset_size):
    """Count subsets of exactly ``subset_size`` positions by their sum.

    Returns a dict mapping each achievable sum to the number of subsets
    (chosen by position) of that size with that sum. Returns an empty
    dict when no subset of the requested size exists.
    """
    n = len(elements)
    if subset_size < 0 or subset_size > n:
        return {}

    # dp[k][s] = number of ways to choose k elements summing to s
    dp = [dict() for _ in range(subset_size + 1)]
    dp[0][0] = 1
    for x in elements:
        for k in range(min(subset_size, n), 0, -1):
            for s, c in dp[k - 1].items():
                dp[k][s + x] = dp[k].get(s + x, 0) + c
    return dp[subset_size]

