import html
import re


def clean_and_wrap(encoded, line_length):
    """Decode base64 HTML-escaped UTF-8 text, unescape entities, tidy
    whitespace, and word-wrap the result to line_length characters."""
    text = base64.b64decode(encoded).decode("utf-8")
    text = html.unescape(text)
    text = re.sub(r"\s+", " ", text).strip()

    lines = []
    current = ""
    for word in text.split(" "):
        if not word:
            continue
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= line_length:
            current += " " + word
        else:
            lines.append(current)
            current = word
    if current:
        lines.append(current)
    return "\n".join(lines)

