import ast


def _skip_string(text, i):
    """Return the index just past the string literal starting at text[i]."""
    quote = text[i]
    n = len(text)
    if text[i:i + 3] == quote * 3:
        delim = quote * 3
    else:
        delim = quote
    j = i + len(delim)
    while j < n:
        if text[j] == '\\':
            j += 2
            continue
        if text.startswith(delim, j):
            return j + len(delim)
        j += 1
    return n


def _match_brace(text, start):
    """Return the index of the '}' matching the '{' at text[start], or None."""
    n = len(text)
    depth = 0
    i = start
    while i < n:
        c = text[i]
        if c == '"' or c == "'":
            i = _skip_string(text, i)
            continue
        if c == '#':
            j = text.find('\n', i)
            if j == -1:
                return None
            i = j + 1
            continue
        if c == '{':
            depth += 1
        elif c == '}':
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return None


def extract_dicts(text):
    """Find every Python dict literal in text and return them as real dicts.

    Only outermost dictionaries are returned, in order of appearance.
    """
    result = []
    i = 0
    n = len(text)
    while i < n:
        if text[i] == '{':
            end = _match_brace(text, i)
            if end is not None:
                try:
                    value = ast.literal_eval(text[i:end + 1])
                except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
                    value = None
                if isinstance(value, dict):
                    result.append(value)
                    i = end + 1
                    continue
        i += 1
    return result

