def closest_pair(points):
    """Return the pair of points with the smallest Euclidean distance.

    Returns (p, q) where p is the point that appears earlier in the input
    list, or None if fewer than two points are given.
    """
    n = len(points)
    if n < 2:
        return None

    # Attach the original index, sort by x (then y) for the divide step.
    pts = sorted(((x, y, i) for i, (x, y) in enumerate(points)),
                 key=lambda t: (t[0], t[1]))

    def dist2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    def key(i, j):
        return (i, j) if i < j else (j, i)

    def better(best, d, i, j):
        # True if (d, i, j) should replace best = (d, bi, bj).
        if d != best[0]:
            return d < best[0]
        return key(i, j) < key(best[1], best[2])

    def solve(lo, hi):
        # Closest pair within pts[lo:hi]; returns (dist2, idx_a, idx_b).
        if hi - lo <= 3:
            best = None
            for a in range(lo, hi):
                for b in range(a + 1, hi):
                    d = dist2(pts[a], pts[b])
                    if best is None or better(best, d, pts[a][2], pts[b][2]):
                        best = (d, pts[a][2], pts[b][2])
            return best

        mid = (lo + hi) // 2
        best = solve(lo, mid)
        right = solve(mid, hi)
        if better(best, right[0], right[1], right[2]):
            best = right

        # Build the strip of points within sqrt(best[0]) of the midline.
        mid_x = pts[mid][0]
        d2 = best[0]
        strip = [k for k in range(lo, hi) if (pts[k][0] - mid_x) ** 2 <= d2]
        strip.sort(key=lambda k: pts[k][1])

        for a in range(len(strip)):
            for b in range(a + 1, len(strip)):
                if (pts[strip[b]][1] - pts[strip[a]][1]) ** 2 > d2:
                    break
                d = dist2(pts[strip[a]], pts[strip[b]])
                if better(best, d, pts[strip[a]][2], pts[strip[b]][2]):
                    best = (d, pts[strip[a]][2], pts[strip[b]][2])
                    d2 = d
        return best

    _, i, j = solve(0, n)
    if i < j:
        return (points[i], points[j])
    return (points[j], points[i])

