import io


def combine_tables_to_csv(tables):
    """Combine a list of tables into a single CSV string.

    Each table is a list of rows (first row is the header). Consecutive
    tables are separated by a line of ``------``. Every line, including the
    last, ends with a newline. An empty list of tables yields an empty string.
    """
    if not tables:
        return ""

    output = io.StringIO()
    writer = csv.writer(output, lineterminator="\n")
    for index, table in enumerate(tables):
        if index > 0:
            writer.writerow(["------"])
        for row in table:
            writer.writerow(row)
    return output.getvalue()

