import ast


def parse_dict_lines(texts):
    """Parse a list of file contents, each line of which is a Python dict literal.

    Returns the list of dictionaries in order: file by file, line by line.
    Raises ValueError if any line is not a valid dictionary literal.
    """
    result = []
    for file_index, text in enumerate(texts):
        for line_number, line in enumerate(text.splitlines(), start=1):
            if not line.strip():
                continue
            try:
                value = ast.literal_eval(line)
            except (ValueError, SyntaxError) as exc:
                raise ValueError(
                    f"File {file_index}, line {line_number}: not a valid "
                    f"dictionary literal: {line!r}"
                ) from exc
            if not isinstance(value, dict):
                raise ValueError(
                    f"File {file_index}, line {line_number}: not a dictionary "
                    f"literal: {line!r}"
                )
            result.append(value)
    return result

