def wrap_each_line(text, width):
    """Word-wrap each line of `text` to at most `width` characters.

    Original line breaks are preserved; each input line is wrapped
    independently. Breaks occur only between words, so a word longer
    than `width` stays whole on its own line.
    """
    wrapped_lines = []
    for line in text.split("\n"):
        words = line.split()
        if not words:
            wrapped_lines.append("")
            continue
        current = words[0]
        for word in words[1:]:
            if len(current) + 1 + len(word) <= width:
                current += " " + word
            else:
                wrapped_lines.append(current)
                current = word
        wrapped_lines.append(current)
    return "\n".join(wrapped_lines)

