import re


def count_stopwords(text, stopwords):
    # Drop URLs: http:// or https:// running to the next whitespace.
    text = re.sub(r'https?://\S+', ' ', text)
    # Split into words: runs of letters, digits, or underscores.
    words = re.findall(r'\w+', text)
    counts = {}
    order = []
    for word in words:
        if word in stopwords:
            if word not in counts:
                counts[word] = 0
                order.append(word)
            counts[word] += 1
    return [(word, counts[word]) for word in order]

