"""Solution: count word occurrences across all cells of a CSV text."""

import csv
import io
from collections import Counter


def _cells(csv_text, delimiter):
    """Yield every cell of the CSV text in order of appearance."""
    if not csv_text:
        return
    if len(delimiter) == 1:
        reader = csv.reader(io.StringIO(csv_text), delimiter=delimiter)
        for row in reader:
            for cell in row:
                yield cell
    else:
        # Fallback for multi-character delimiters (not supported by csv module).
        for line in csv_text.splitlines():
            for cell in line.split(delimiter):
                yield cell


def most_common_csv_words(csv_text, delimiter):
    """Return [(word, count)] sorted by count descending.

    Words with equal counts keep the order in which they first occur
    in the CSV text.
    """
    counts = Counter()
    first_seen = {}
    for cell in _cells(csv_text, delimiter):
        word = cell.strip()
        if not word:
            continue
        if word not in first_seen:
            first_seen[word] = len(first_seen)
        counts[word] += 1

    return sorted(counts.items(), key=lambda kv: (-kv[1], first_seen[kv[0]]))

