"""Total up match statistics from a CSV file plus per-team dictionaries."""

import csv
import io


def _to_number(value):
    """Convert a CSV cell / dict value into a number, treating blanks as 0."""
    if value is None:
        return 0
    if isinstance(value, bool):
        return int(value)
    if isinstance(value, (int, float)):
        return value
    text = str(value).strip()
    if text == "":
        return 0
    try:
        return int(text)
    except ValueError:
        try:
            return float(text)
        except ValueError:
            return 0


def _sum_dict(mapping):
    """Sum all values of a mapping (empty/None contributes nothing)."""
    if not mapping:
        return 0
    total = 0
    for value in mapping.values():
        total = total + _to_number(value)
    return total


def total_goals_and_penalties(csv_text, goals, penalties):
    """Return {'goals': ..., 'penalties': ...} for a CSV plus extra dicts.

    ``csv_text`` is the text of a CSV file whose header row contains
    ``goals`` and ``penalties`` columns (one row per team).  ``goals`` and
    ``penalties`` are dicts mapping team names to additional goals and
    penalties.  An empty ``csv_text`` contributes nothing.
    """
    total_goals = _sum_dict(goals)
    total_penalties = _sum_dict(penalties)

    if csv_text is None or str(csv_text).strip() == "":
        return {"goals": total_goals, "penalties": total_penalties}

    reader = csv.DictReader(io.StringIO(str(csv_text)))
    if reader.fieldnames is None:
        return {"goals": total_goals, "penalties": total_penalties}

    # Normalise header names (case-insensitive, surrounding whitespace removed)
    # while remembering the original name so we can look values up in each row.
    name_map = {}
    for name in reader.fieldnames:
        if name is None:
            continue
        name_map[str(name).strip().lower()] = name

    goals_key = name_map.get("goals")
    penalties_key = name_map.get("penalties")

    if goals_key is not None or penalties_key is not None:
        for row in reader:
            # DictReader rows may be shorter than the header; guard with .get
            if goals_key is not None:
                total_goals = total_goals + _to_number(row.get(goals_key))
            if penalties_key is not None:
                total_penalties = total_penalties + _to_number(row.get(penalties_key))

    return {"goals": total_goals, "penalties": total_penalties}

