"""Utility to check whether a JSON text is a list of JSON objects."""

import json


def is_list_of_objects(json_text):
    """Return True if ``json_text`` is valid JSON holding a list whose items
    are all JSON objects (an empty list counts as True).

    Returns False for anything else, including invalid JSON, non-list JSON
    values, lists containing non-object items, and non-string input.
    """
    if not isinstance(json_text, str):
        return False

    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, ValueError, TypeError, RecursionError):
        return False

    if not isinstance(data, list):
        return False

    return all(isinstance(item, dict) for item in data)

