"""Helpers for finding files whose contents match a given MD5 digest."""

import hashlib


def files_matching_md5(files, target_hash):
    """Return a sorted list of names of files whose MD5 matches ``target_hash``.

    ``files`` is a dict mapping file names to their contents as bytes.
    ``target_hash`` is an MD5 digest as a lowercase hex string.
    """
    if not target_hash:
        return []

    target = target_hash.lower()

    matches = []
    for name, contents in files.items():
        if contents is None:
            continue
        if not isinstance(contents, (bytes, bytearray, memoryview)):
            contents = str(contents).encode("utf-8")
        digest = hashlib.md5(bytes(contents)).hexdigest()
        if digest == target:
            matches.append(name)

    return sorted(matches)

