import json
import re

_EMAIL_RE = re.compile(r"^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$")


def _is_email(value):
    """Return True if the given value is a string that looks like an email address."""
    return isinstance(value, str) and _EMAIL_RE.match(value.strip()) is not None


def clean_json_record(json_str):
    """Clean a flat JSON object given as a string.

    Keys whose value is null are dropped, and any string value that is an
    email address is replaced with the string "None".

    Returns a dict with two entries:
      - "data":   the cleaned object (keys in their original order)
      - "counts": a mapping of each remaining value to its number of occurrences
    """
    record = json.loads(json_str)

    if not isinstance(record, dict):
        record = {}

    data = {}
    counts = {}
    for key, value in record.items():
        if value is None:
            continue
        if _is_email(value):
            value = "None"
        data[key] = value
        try:
            counts[value] = counts.get(value, 0) + 1
        except TypeError:
            # Unhashable value: fall back to using its string representation.
            str_key = str(value)
            counts[str_key] = counts.get(str_key, 0) + 1

    return {"data": data, "counts": counts}

