"""Utilities for analysing log lines."""

import re

# Leading timestamp such as "2021-06-15 09:45:00" (optionally with a 'T'
# separator and/or fractional seconds).
_TIMESTAMP_RE = re.compile(
    r'^\s*\d{4}-\d{2}-\d{2}[ T]\d{1,2}:\d{2}(?::\d{2})?(?:\.\d+)?\s*'
)

# A time of day anywhere in the line.
_TIME_RE = re.compile(r'\b(\d{1,2}):(\d{2})(?::\d{2})?\b')


def _is_error_line(line):
    """Return True if the log line is an ERROR entry."""
    if not isinstance(line, str):
        return False
    rest = _TIMESTAMP_RE.sub('', line, count=1)
    if rest is not line:
        # A leading timestamp was found: the level is the first token after it.
        level = rest.split(None, 1)[0].strip().rstrip(':').upper() if rest.strip() else ''
        if level:
            return level == 'ERROR'
    # Fallback for lines without a leading timestamp.
    return re.search(r'\bERROR\b', line) is not None


def _time_of_day(line):
    """Extract the (hour, minute) time of day from a log line, or None."""
    if not isinstance(line, str):
        return None
    match = _TIME_RE.search(line)
    if match is None:
        return None
    hour = int(match.group(1))
    minute = int(match.group(2))
    if not (0 <= hour <= 23 and 0 <= minute <= 59):
        return None
    return (hour, minute)


def error_times_and_average(logs):
    """Collect the times of day of all ERROR log entries and their average.

    Returns a tuple ``(times, average)`` where ``times`` is a list of
    ``(hour, minute)`` tuples in log order and ``average`` is the average time
    of day as an ``(hour, minute)`` tuple computed in whole minutes and
    rounded down.  If there are no ERROR entries, ``([], (0, 0))`` is
    returned.
    """
    times = []
    if logs:
        for line in logs:
            if _is_error_line(line):
                tod = _time_of_day(line)
                if tod is not None:
                    times.append(tod)

    if not times:
        return ([], (0, 0))

    total_minutes = sum(hour * 60 + minute for hour, minute in times)
    average_minutes = total_minutes // len(times)
    return (times, (average_minutes // 60, average_minutes % 60))

