"""Utility for decoding a hex-encoded ``q`` query parameter of a URL."""

import re
from urllib.parse import parse_qs, urlparse

# Strict hexadecimal string: only hex digits, no whitespace/other characters.
_HEX_RE = re.compile(r"[0-9a-fA-F]+")


def _extract_query(url):
    """Return the query string of *url* (possibly the string itself)."""
    parsed = urlparse(url)
    query = parsed.query
    if not query:
        # Be forgiving with inputs that are just a query string
        # (e.g. "q=4a4b4c" or "?q=4a4b4c" handled above).
        if "=" in url and "://" not in url and "?" not in url:
            query = url
    return query


def decode_hex_query_param(url):
    """Decode the ``q`` query parameter of *url* from hex to UTF-8 text.

    Returns ``None`` when there is no ``q`` parameter, when its value is not
    a valid hexadecimal string, or when the resulting bytes are not valid
    UTF-8.
    """
    if not isinstance(url, str):
        return None

    try:
        query = _extract_query(url)
        params = parse_qs(query, keep_blank_values=True)
    except Exception:
        return None

    values = params.get("q")
    if not values:
        return None
    value = values[0]

    # Must be a non-empty, even-length string of hex digits.
    if not value or len(value) % 2 != 0:
        return None
    if _HEX_RE.fullmatch(value) is None:
        return None

    try:
        raw = bytes.fromhex(value)
    except ValueError:
        return None

    try:
        return raw.decode("utf-8")
    except UnicodeDecodeError:
        return None

