"""Count subset sums for subsets of a fixed size."""


def count_subset_sums(elements, subset_size):
    """Return a dict mapping each achievable sum to the number of subsets
    of exactly ``subset_size`` elements (chosen by position) that sum to it.

    If no subset of that size exists, an empty dict is returned.
    """
    elements = tuple(elements)
    n = len(elements)
    k = subset_size

    # Validate the subset size: it must be a non-negative integer no larger
    # than the number of elements.
    if isinstance(k, bool):
        k = int(k)
    elif isinstance(k, int):
        pass
    else:
        # Accept other integral types (e.g. numpy ints, integral floats).
        try:
            as_int = int(k)
        except (TypeError, ValueError):
            return {}
        if as_int != k:
            return {}
        k = as_int
    if k < 0 or k > n:
        return {}

    # dp[j] maps a sum to the number of ways to choose j elements with that sum.
    dp = [dict() for _ in range(k + 1)]
    dp[0][0] = 1

    for value in elements:
        # Iterate downwards so each element is used at most once.
        for j in range(k, 0, -1):
            if not dp[j - 1]:
                continue
            target = dp[j]
            for s, c in dp[j - 1].items():
                new_sum = s + value
                target[new_sum] = target.get(new_sum, 0) + c
        # j == 0 case: nothing to do (the empty subset is already recorded).

    return dict(dp[k])

