"""Find the first row index whose first field matches a target value in CSV files."""

import csv
import io


def find_target_rows(target_value, csv_files):
    """Return {file_name: index of first row whose first field == target_value}.

    Files with no matching row are omitted from the result. Row indices are
    zero-based and count every row of the file (including header rows).
    """
    result = {}
    for name, text in csv_files.items():
        reader = csv.reader(io.StringIO(text))
        for index, row in enumerate(reader):
            if row and row[0] == target_value:
                result[name] = index
                break
    return result

