import hashlib


def salted_password_hashes(salt, users):
    """Return a dict mapping each user id to the SHA-256 hex digest of
    the user's password with the salt appended (both encoded as UTF-8)."""
    if not isinstance(salt, str):
        raise TypeError("salt must be a string")
    result = {}
    for user_id, password in users:
        digest = hashlib.sha256((password + salt).encode("utf-8")).hexdigest()
        result[user_id] = digest
    return result

