"""Convert a dict of columns into CSV text."""


def _is_number(value):
    """Return True if value should be written unquoted (a number)."""
    if isinstance(value, bool):
        # Booleans are a subclass of int; treat them as plain values
        # written unquoted, matching typical CSV output.
        return True
    return isinstance(value, (int, float))


def _format_field(value):
    """Format a single CSV field according to the rules."""
    if _is_number(value):
        return str(value)
    text = value if isinstance(value, str) else str(value)
    return '"' + text.replace('"', '""') + '"'


def columns_to_csv(columns):
    """Return the table described by ``columns`` as CSV text.

    ``columns`` is a dict mapping column names to equal-length lists of
    values (numbers or strings).  The first row holds the column names,
    followed by one row per record.  Columns keep the dict's order and no
    index column is added.  Non-numeric fields (including headers) are
    wrapped in double quotes with embedded quotes doubled; numbers are
    left unquoted.  Every line ends with a newline.
    """
    if not columns:
        return ""

    names = list(columns.keys())
    lengths = {len(columns[name]) for name in names}
    if len(lengths) > 1:
        raise ValueError("all columns must have the same length")
    n_rows = lengths.pop() if lengths else 0

    lines = [",".join(_format_field(name) for name in names)]
    for i in range(n_rows):
        lines.append(
            ",".join(_format_field(columns[name][i]) for name in names)
        )
    return "".join(line + "\n" for line in lines)

