"""Utilities for converting CSV text into JSON-friendly records."""

import csv
import io


def csv_to_records(csv_text):
    """Parse CSV text (first row is the header) into a list of dicts.

    Every value is kept as a string, exactly as it appears in the file.
    Empty input, or a header with no data rows, yields an empty list.
    """
    if csv_text is None:
        return []
    if not isinstance(csv_text, str):
        csv_text = str(csv_text)
    if not csv_text.strip():
        return []

    reader = csv.reader(io.StringIO(csv_text, newline=""))
    try:
        header = next(reader)
    except StopIteration:
        return []

    records = []
    for row in reader:
        if not row:
            # Skip completely blank lines.
            continue
        record = {}
        for i, column in enumerate(header):
            record[column] = row[i] if i < len(row) else ""
        records.append(record)
    return records

