"""Utilities for counting top-level keys across a list of JSON records."""

import ast
import json


def _parse_text_dict(text):
    """Parse a text snippet that is supposed to hold a dictionary.

    Returns the dict when the text holds a dictionary, otherwise ``None``.
    Both JSON-style text (``{"a": 1}``) and Python-literal style text
    (``{'a': 1}``) are supported.
    """
    if not isinstance(text, str):
        return None

    stripped = text.strip()
    if not stripped:
        return None

    # First try strict JSON, since that is the most common representation.
    try:
        parsed = json.loads(stripped)
    except (ValueError, TypeError):
        parsed = None

    if parsed is None:
        # Fall back to Python literal syntax (single quotes, True/None, ...).
        try:
            parsed = ast.literal_eval(stripped)
        except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
            return None

    if isinstance(parsed, dict):
        return parsed
    return None


def _as_record(item):
    """Normalize a list entry into a dict, or ``None`` when it isn't a record."""
    if isinstance(item, dict):
        return item
    if isinstance(item, str):
        return _parse_text_dict(item)
    return None


def count_record_keys(json_text):
    """Count how many records each top-level key appears in.

    ``json_text`` is a JSON string holding a list of records.  Each record is
    either a JSON object or a string whose text is a dictionary written out as
    text (e.g. ``'{"name": "Jane"}'``).  String items that do not hold a
    dictionary are skipped, as are non-object/non-string items.

    Returns a dict mapping each top-level key to the number of records in
    which it appears, e.g. ``{'name': 2, 'age': 1}``.
    """
    if isinstance(json_text, (list, tuple)):
        records = json_text
    else:
        try:
            records = json.loads(json_text)
        except (ValueError, TypeError):
            return {}

    if isinstance(records, dict):
        # A single object was supplied instead of a list of them.
        records = [records]

    if not isinstance(records, (list, tuple)):
        return {}

    counts = {}
    for item in records:
        record = _as_record(item)
        if record is None:
            continue
        for key in record:
            counts[key] = counts.get(key, 0) + 1
    return counts

