    if cleaned[:2].lower() == "0x":
        cleaned = cleaned[2:]
    # Remove any embedded whitespace so that pretty-printed hex works.
    cleaned = "".join(cleaned.split())

    if not cleaned:
        raise ValueError("compressed_hex is empty; expected gzip-compressed data")

    if len(cleaned) % 2 != 0:
