"""Find the most frequent field value in CSV text."""

import csv
import io
from collections import Counter


def most_common_csv_value(csv_text):
    """Return the most common field value in ``csv_text`` as ``(value, count)``.

    The CSV text is parsed row by row; every field of every row is considered.
    Surrounding whitespace of each value is ignored.  Returns ``None`` when the
    text contains no (non-empty) fields.
    """
    if csv_text is None:
        return None

    if not isinstance(csv_text, str):
        csv_text = str(csv_text)

    counts = Counter()
    reader = csv.reader(io.StringIO(csv_text))
    for row in reader:
        for field in row:
            value = field.strip()
            if value:
                counts[value] += 1

    if not counts:
        return None

    value, count = counts.most_common(1)[0]
    return (value, count)

