import hashlib
import re


def _file_name(path):
    """Return the last path component of a '/'-separated path."""
    if not isinstance(path, str):
        path = str(path)
    # The separator is '/' per the spec; take the last component.
    if "/" in path:
        return path.rsplit("/", 1)[-1]
    return path


def _to_bytes(content):
    """Coerce file contents to bytes so they can be hashed."""
    if isinstance(content, bytes):
        return content
    if isinstance(content, bytearray):
        return bytes(content)
    if isinstance(content, memoryview):
        return content.tobytes()
    if isinstance(content, str):
        return content.encode("utf-8")
    # Fall back: try bytes(content) for any other buffer-like object.
    try:
        return bytes(content)
    except Exception:
        return str(content).encode("utf-8")


def hash_matching_files(files, pattern):
    """Return {path: sha256_hex} for files whose *file name* matches ``pattern``.

    ``files`` maps '/'-separated paths to file contents (bytes).  ``pattern`` is
    a regular expression (a string or an already-compiled ``re`` pattern); a
    file is selected when its file name (the last path component) *contains* a
    match for the pattern (i.e. ``re.search`` semantics).
    """
    if files is None:
        return {}

    if isinstance(pattern, (str, bytes)):
        if isinstance(pattern, bytes):
            pattern = pattern.decode("utf-8")
        regex = re.compile(pattern)
    else:
        # Assume it is already a compiled pattern (or duck-typed equivalent).
        regex = pattern

    search = regex.search

    result = {}
    for path, content in files.items():
        name = _file_name(path)
        try:
            matched = search(name) is not None
        except Exception:
            matched = False
        if matched:
            result[path] = hashlib.sha256(_to_bytes(content)).hexdigest()
    return result

