import struct


def hex_to_rounded_float(hex_key):
    """Decode a big-endian 32-bit IEEE 754 float from a hex string and round
    it to 2 decimal places.

    Example: hex_to_rounded_float('470FC614') -> 36806.08
    """
    if not isinstance(hex_key, str):
        raise TypeError("hex_key must be a string of 8 hexadecimal digits")

    cleaned = hex_key.strip()
    if cleaned.lower().startswith("0x"):
        cleaned = cleaned[2:]

    if len(cleaned) != 8:
        raise ValueError("hex_key must contain exactly 8 hexadecimal digits")

    try:
        raw = bytes.fromhex(cleaned)
    except ValueError:
        raise ValueError("hex_key must contain only hexadecimal digits")

    (value,) = struct.unpack(">f", raw)
    return round(value, 2)

