import math


def sine_of_summed_values(nested_dict):
    """Sum values per key across all inner dicts (excluding 'ele') and
    return a dict mapping each remaining key to the sine of its total."""
    totals = {}
    for inner in nested_dict.values():
        for key, value in inner.items():
            if key == "ele":
                continue
            totals[key] = totals.get(key, 0) + value
    return {key: math.sin(total) for key, total in totals.items()}

