import json


def count_json_keys(documents):
    """Count in how many documents each top-level JSON key appears.

    Args:
        documents: An iterable of strings, each containing a JSON object.

    Returns:
        A dict mapping each top-level key to the number of documents in
        which that key appears. Keys of nested objects are ignored.
    """
    counts = {}
    for document in documents:
        if not isinstance(document, str):
            continue
        try:
            parsed = json.loads(document)
        except (ValueError, TypeError):
            # Not valid JSON -- nothing to count from this entry.
            continue
        if not isinstance(parsed, dict):
            continue
        for key in parsed:
            counts[key] = counts.get(key, 0) + 1
    return counts

