"""Reverse the rows of CSV text while keeping quoted fields intact."""


def _split_records(csv_text):
    """Split CSV text into logical records (rows).

    A record ends at a newline that is not inside a quoted field.
    Each returned record keeps its original text, including its
    terminating newline if it had one.
    """
    records = []
    n = len(csv_text)
    start = 0
    i = 0
    in_quotes = False
    while i < n:
        c = csv_text[i]
        if in_quotes:
            if c == '"':
                # A doubled quote ("") is an escaped quote inside a field.
                if i + 1 < n and csv_text[i + 1] == '"':
                    i += 2
                    continue
                in_quotes = False
        else:
            if c == '"':
                in_quotes = True
            elif c == '\n':
                records.append(csv_text[start:i + 1])
                start = i + 1
        i += 1
    if start < n:
        records.append(csv_text[start:])
    return records


def reverse_csv_rows(csv_text):
    """Return CSV text with the same rows in reverse order.

    Each output row ends with a newline. Quoted fields (including ones
    containing commas or line breaks) are kept intact as single fields.
    """
    if not csv_text:
        return ""
    records = _split_records(csv_text)
    out = []
    for record in reversed(records):
        if record.endswith('\n'):
            out.append(record)
        else:
            out.append(record + '\n')
    return ''.join(out)

