"""Convert a base64-encoded JSON object into header-less CSV text."""

import base64
import binascii
import csv
import io
import json


def _decode_base64(raw_string):
    """Decode a base64 string (accepting str or bytes) into text."""
    if isinstance(raw_string, str):
        raw_string = raw_string.encode("ascii", "ignore")
    elif isinstance(raw_string, (bytearray, memoryview)):
        raw_string = bytes(raw_string)
    elif not isinstance(raw_string, bytes):
        raw_string = str(raw_string).encode("utf-8")

    # Strip whitespace (newlines etc. are legal in base64 payloads).
    compact = b"".join(raw_string.split())

    # Tolerate missing padding.
    if compact and len(compact) % 4:
        compact += b"=" * (-len(compact) % 4)

    last_error = None
    for decoder in (base64.b64decode, base64.urlsafe_b64decode):
        try:
            return decoder(compact).decode("utf-8")
        except (binascii.Error, ValueError, UnicodeDecodeError) as exc:
            last_error = exc
    raise ValueError("Invalid base64-encoded JSON: %s" % (last_error,))


def base64_json_to_csv(raw_string):
    """Return the contents of a base64-encoded JSON object as CSV text.

    The CSV has no header row; there is one ``key,value`` row per entry of
    the JSON object, in the object's order, and every row ends with a
    newline.

    >>> base64_json_to_csv('eyJrZXkiOiAiVmFsdWUifQ==')
    'key,Value\\n'
    """
    text = _decode_base64(raw_string)
    data = json.loads(text)

    if not isinstance(data, dict):
        raise ValueError("JSON payload must be an object, got %s" % type(data).__name__)

    output = io.StringIO()
    writer = csv.writer(output, lineterminator="\n")
    for key, value in data.items():
        writer.writerow([key, value])
    return output.getvalue()

