import json


def _make_hashable(value):
    """Return a hashable stand-in for ``value`` if it isn't already hashable."""
    try:
        hash(value)
        return value
    except TypeError:
        # Lists / dicts are valid JSON values but are not hashable, so use a
        # stable textual representation as the dictionary key instead.
        return json.dumps(value, sort_keys=True, default=str)


def count_key_values(json_documents, key):
    """Count, per distinct value of ``key``, in how many documents it occurs.

    Args:
        json_documents: Iterable of strings, each expected to be a JSON object.
        key: The object key whose values should be counted.

    Returns:
        A dict mapping each value taken by ``key`` to the number of documents
        in which the key has that value. Documents that do not contain the
        key (or that cannot be parsed as JSON objects) are ignored.
    """
    counts = {}
    for document in json_documents or []:
        if not isinstance(document, str):
            continue
        try:
            parsed = json.loads(document)
        except (ValueError, TypeError):
            continue
        if not isinstance(parsed, dict) or key not in parsed:
            continue
        value = _make_hashable(parsed[key])
        counts[value] = counts.get(value, 0) + 1
    return counts

