import re


def count_non_stopwords(sentence, stopwords):
    """Return the number of words in ``sentence`` that are not stopwords.

    Punctuation is ignored and words are compared case-insensitively
    against the (lowercase) stopword list.
    """
    if not sentence:
        return 0
    stop = {str(w).lower() for w in (stopwords or [])}
    # Words are maximal runs of alphanumeric characters, so any
    # surrounding punctuation is ignored.
    words = re.findall(r"[^\W_]+", str(sentence), flags=re.UNICODE)
    return sum(1 for word in words if word.lower() not in stop)

