"""Solution: count words in the "text" field of a JSON string."""

import json


def count_words_in_json(json_string):
    """Return a dict mapping each word in the JSON object's "text" field to
    its number of occurrences.

    Words are compared case-insensitively (returned in lowercase) and
    non-alphanumeric characters are removed from each whitespace-separated
    token. Invalid JSON or a missing "text" field yields an empty dict.
    """
    if not isinstance(json_string, str):
        return {}

    try:
        data = json.loads(json_string)
    except (json.JSONDecodeError, ValueError, TypeError):
        return {}

    if not isinstance(data, dict):
        return {}

    if "text" not in data:
        return {}

    text = data["text"]
    if not isinstance(text, str):
        return {}

    counts = {}
    for token in text.split():
        word = "".join(ch for ch in token if ch.isalnum()).lower()
        if word:
            counts[word] = counts.get(word, 0) + 1
    return counts

