import base64
import binascii
import json
import unicodedata


def decode_base64_json_values(json_text):
    """Decode a JSON object whose values are base64-encoded UTF-8 strings.

    Args:
        json_text: A JSON object (as a string) mapping keys to base64 strings.

    Returns:
        A dict with the same keys, each value being the decoded text
        normalized to Unicode NFC form.

    Raises:
        ValueError: If ``json_text`` is not valid JSON, is not a JSON object,
            a value is not a string, a value is not valid base64, or the
            decoded bytes are not valid UTF-8.
    """
    if isinstance(json_text, (bytes, bytearray)):
        try:
            json_text = bytes(json_text).decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(f"json_text is not valid UTF-8: {exc}") from exc
    if not isinstance(json_text, str):
        raise ValueError("json_text must be a string containing a JSON object")

    try:
        data = json.loads(json_text)
    except ValueError as exc:  # json.JSONDecodeError subclasses ValueError
        raise ValueError(f"Invalid JSON: {exc}") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON text must be an object (dict)")

    result = {}
    for key, value in data.items():
        if not isinstance(value, str):
            raise ValueError(f"Value for key {key!r} is not a base64 string")
        try:
            raw = base64.b64decode(value, validate=True)
        except (binascii.Error, ValueError) as exc:
            raise ValueError(f"Value for key {key!r} is not valid base64: {exc}") from exc
        try:
            text = raw.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError(f"Value for key {key!r} is not valid UTF-8: {exc}") from exc
        result[key] = unicodedata.normalize("NFC", text)

    return result

